std::string decimal(std::string s){
 bool negative=!s.empty()&&s[0]=='-';if(!s.empty()&&(s[0]=='-'||s[0]=='+'))s.erase(0,1);
 auto e=s.find_first_of("eE");int exp=0;if(e!=s.npos){exp=std::stoi(s.substr(e+1));s=s.substr(0,e);}
 auto dot=s.find('.');int before=dot==s.npos?int(s.size()):int(dot);if(dot!=s.npos)s.erase(dot,1);
 int position=before+exp;std::string result;
 if(position<=0)result="0."+std::string(-position,'0')+s;
 else if(position>=int(s.size()))result=s+std::string(position-int(s.size()),'0');
 else result=s.substr(0,position)+"."+s.substr(position);
 while(result.size()>1&&result[0]=='0'&&result[1]!='.')result.erase(0,1);
 if(result.find('.')!=result.npos){while(result.back()=='0')result.pop_back();if(result.back()=='.')result.pop_back();}
 if(result.empty()||result=="0")return "0";return (negative?"-":"")+result;
}
