 const std::map<std::string,std::string>enums{{"CARTESIAN","Cartesian"},{"ELLIPSOIDAL","ellipsoidal"},{"VERTICAL","vertical"},{"SPHERICAL","spherical"},{"EAST","east"},{"NORTH","north"},{"UP","up"},{"WEST","west"},{"SOUTH","south"},{"DOWN","down"},{"GEOCENTRICX","geocentricX"},{"GEOCENTRICY","geocentricY"},{"GEOCENTRICZ","geocentricZ"},{"PARAMETRIC","parametric"},{"TEMPORAL","temporal"},{"ORDINAL","ordinal"},{"AFFINE","affine"},{"CYLINDRICAL","cylindrical"},{"POLAR","polar"},{"FUTURE","future"},{"PAST","past"},{"UNSPECIFIED","unspecified"},{"CLOCKWISE","clockwise"},{"COUNTERCLOCKWISE","counterClockwise"},{"AWAYFROM","awayFrom"},{"TOWARDS","towards"},{"COLUMNPOSITIVE","columnPositive"},{"ROWPOSITIVE","rowPositive"},{"DISPLAYRIGHT","displayRight"},{"DISPLAYLEFT","displayLeft"},{"DISPLAYUP","displayUp"},{"DISPLAYDOWN","displayDown"},{"FORWARD","forward"},{"AFT","aft"},{"PORT","port"},{"STARBOARD","starboard"}};
