bool direct(const UsdPrim&p){for(auto&s:p.GetAppliedSchemas())if(s==TfToken("GeospatialCRSBindingAPI"))return true;return false;}
std::string wkt(const UsdPrim&p){auto a=p.GetAttribute(TfToken("crs:wkt"));TfToken t;if(!a||a.GetTypeName()!=SdfValueTypeNames->Token||a.GetVariability()!=SdfVariabilityUniform)throw Failure("property-type","crs:wkt");if(a.GetNumTimeSamples())throw Failure("uniform-time-samples","crs:wkt");if(!a.Get(&t,UsdTimeCode::Default()))throw Failure("unavailable-property","crs:wkt");return t.GetString();}
void validRole(const UsdPrim&p){if(direct(p)&&!UsdGeomXformable(p))throw Failure("invalid-binding-role",p.GetPath().GetString());if(p.GetTypeName()==TfToken("CoordinateReferenceSystem")&&!direct(p))return;if(!direct(p)||p.GetTypeName()==TfToken("GeospatialDataSource"))for(auto name:{"crs:position","crs:orientation"}){auto a=p.GetAttribute(TfToken(name));if(a&&a.HasAuthoredValueOpinion())throw Failure("invalid-placement-role",name);}}
Vec placement(const UsdPrim&p,const char*name,UsdTimeCode t){auto a=p.GetAttribute(TfToken(name));Vec v;if(!a||a.GetTypeName()!=SdfValueTypeNames->Double3||a.GetVariability()!=SdfVariabilityVarying)throw Failure("property-type",name);if(!a.Get(&v,t))throw Failure("unavailable-placement",name);finite(v);return v;}
GfQuatd quat(const Vec&angles){Vec r(std::fmod(angles[0],720)*PI/180,std::fmod(angles[1],720)*PI/180,std::fmod(angles[2],720)*PI/180);return GfQuatd(std::cos(r[0]/2),Vec(0,0,-std::sin(r[0]/2)))*GfQuatd(std::cos(r[1]/2),Vec(std::sin(r[1]/2),0,0))*GfQuatd(std::cos(r[2]/2),Vec(0,std::sin(r[2]/2),0));}
