GfMatrix4d local(const UsdPrim&p,UsdTimeCode t,bool*reset=nullptr){UsdGeomXformable x(p);GfMatrix4d m(1);bool r=false;if(x&&!x.GetLocalTransformation(&m,&r,t))throw Failure("ordinary-transform","Unavailable ordinary stack");if(reset)*reset=r;return m;}
